const webhookData = $('Contact Triage Webhook').first().json;
const payload = webhookData.body || webhookData;
const inquiryId = String(payload.inquiry_id || '');
const name = String(payload.name || 'Portfolio Visitor').trim();
const email = String(payload.email || '').trim();
const subject = payload.subject ? String(payload.subject).trim() : '(No subject)';
const message = String(payload.message || '').trim();

const recruiterKeywords = [
  'recruiter', 'recruiting', 'talent acquisition', 'hiring', 'interview',
  'full-time', 'full time', 'job opening', 'position', 'candidate', 'compensation', 'salary'
];
const freelanceKeywords = [
  'freelance', 'contract', 'project quote', 'quote', 'mvp', 'consulting',
  'consultant', 'client project', 'budget', 'timeline', 'build a website', 'web app'
];

const classifyDeterministic = (subj, msg) => {
  const text = `${subj} ${msg}`.toLowerCase();
  if (recruiterKeywords.some((kw) => text.includes(kw))) return 'recruiter';
  if (freelanceKeywords.some((kw) => text.includes(kw))) return 'freelance project';
  return 'general inquiry';
};

let intentCategory = classifyDeterministic(subject, message);
let triageSummary = `${intentCategory} from ${name}: ${message.slice(0, 220)}`;

const geminiKey = ($env.GEMINI_API_KEY || '').trim();
if (geminiKey) {
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 4000);
    const prompt = [
      'Classify this portfolio contact message into exactly one intent_category from:',
      '"recruiter", "freelance project", or "general inquiry".',
      'Tie-break order: recruiter > freelance project > general inquiry.',
      'Default ambiguous or ultra-short messages to "general inquiry".',
      'Return strict JSON only: {"intent_category":"...","triage_summary":"<=240 chars summary"}.',
      `Name: ${name}`,
      `Subject: ${subject}`,
      `Message: ${message}`
    ].join('\n');

    const res = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash-lite:generateContent?key=${encodeURIComponent(geminiKey)}`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: { responseMimeType: 'application/json', temperature: 0 }
        }),
        signal: controller.signal
      }
    );
    clearTimeout(timer);
    if (res.ok) {
      const data = await res.json();
      const rawText = data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
      const parsed = JSON.parse(rawText);
      if (['recruiter', 'freelance project', 'general inquiry'].includes(parsed.intent_category)) {
        intentCategory = parsed.intent_category;
      }
      if (typeof parsed.triage_summary === 'string' && parsed.triage_summary.trim()) {
        triageSummary = parsed.triage_summary.trim();
      }
    }
  } catch (_err) {
    // Deterministic fallback already populated above
  }
}

const summaryTruncated = triageSummary.slice(0, 500);
const excerptTruncated = message.slice(0, 1000);

const discordPayload = {
  embeds: [
    {
      title: `[Contact Lead: ${intentCategory.toUpperCase()}] ${name}`,
      color: intentCategory === 'recruiter' ? 3718904 : intentCategory === 'freelance project' ? 1752220 : 10070709,
      fields: [
        { name: 'Name', value: name || 'Unknown', inline: true },
        { name: 'Email', value: email || 'Unknown', inline: true },
        { name: 'Intent Category', value: intentCategory, inline: true },
        { name: 'Subject', value: subject.slice(0, 200) || '(No subject)', inline: false },
        { name: 'Summary', value: summaryTruncated || 'N/A', inline: false },
        { name: 'Message Excerpt', value: excerptTruncated || 'N/A', inline: false }
      ],
      timestamp: new Date().toISOString()
    }
  ]
};

return [{
  json: {
    inquiry_id: inquiryId,
    intent_category: intentCategory,
    triage_summary: summaryTruncated,
    discordPayload
  }
}];

const crypto = require('crypto');
const discordResult = $input.first().json || {};
const classified = $('Classify Intent (Gemini + Fallback)').first().json;
const secret = ($env.AUTOMATION_WEBHOOK_SECRET || '').trim();

if (!secret) {
  throw new Error('AUTOMATION_WEBHOOK_SECRET environment variable is required.');
}

const discordUrlConfigured = Boolean(($env.DISCORD_WEBHOOK_URL || '').trim());
const notificationSent = discordUrlConfigured && !discordResult.error;

const callbackPayload = {
  inquiry_id: classified.inquiry_id,
  intent_category: classified.intent_category,
  triage_summary: classified.triage_summary,
  notification_sent: notificationSent
};

const rawBody = JSON.stringify(callbackPayload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');

return [{
  json: {
    rawBody,
    timestamp,
    signature
  }
}];
